1	import Darwin
2	import WorkroomSessionProtocol
3	
4	enum SessionDaemonStart {
5	  case running(SessionDaemon)
6	  case lockHeld
7	  case failed(String)
8	}
9	
10	final class SessionDaemon {
11	  static let replayCapacity = 256 * 1024
12	  static let clientOutputLimit = 4 * 1024 * 1024
13	  static let sessionInputLimit = 1024 * 1024
14	  static let maximumConnections = 64
15	  static let maximumSessions = 256
16	  static let idleTimeoutMilliseconds: Int32 = 10000
17	  static let replayChunkSize = 32 * 1024
18	  /// How long to leave a reattached session's pty bumped before resizing it back and signaling —
19	  /// long enough for the child to actually be scheduled and observe the transient size (see
20	  /// `SessionPTY.bumpedRowCount`), short enough nobody notices. Deferred through the poll loop
21	  /// rather than a blocking sleep: this daemon is single-threaded and serves every session across
22	  /// every open project, so blocking here would freeze all of them for the duration, worst-case
23	  /// stacking to N × this value when many persisted tabs reattach at once on relaunch.
24	  static let redrawSettleSeconds: Double = 0.03
25	
26	  private let socketPath: String
27	  private let idleTimeout: Int32
28	  private let listener: Int32
29	  private let lockDescriptor: Int32
30	  private let signalPipe: SessionSignalPipe
31	
32	  private var sessions: [SessionIdentifier: PTYSession] = [:]
33	  private var sessionsByMaster: [Int32: SessionIdentifier] = [:]
34	  private var connections: [Int32: SessionConnection] = [:]
35	  private var closingDescriptors: [Int32] = []
36	  /// Sessions bumped by `attach()`, awaiting their non-blocking resize-back-and-signal once
37	  /// `redrawSettleSeconds` has elapsed. Keyed by identifier, not master fd, so a session that gets
38	  /// killed and its fd reused before the deadline can't cause this to resize/signal the WRONG pty.
39	  private var pendingRedraws: [SessionIdentifier: PendingRedraw] = [:]
40	
41	  private struct PendingRedraw {
42	    let deadline: Double
43	    let columns: UInt16
44	    let rows: UInt16
45	  }
46	
47	  static func start(
48	    socketPath: String,
49	    idleTimeoutMilliseconds: Int32 = SessionDaemon.idleTimeoutMilliseconds
50	  ) -> SessionDaemonStart {
51	    signal(SIGPIPE, SIG_IGN)
52	    signal(SIGHUP, SIG_IGN)
53	
54	    guard let lock = SessionSocket.acquireLock(path: socketPath + ".lock") else {
55	      return .lockHeld
56	    }
57	    guard let signalPipe = SessionSignalPipe(signals: [SIGCHLD]) else {
58	      SessionIO.close(lock)
59	      return .failed("unable to create the signal pipe")
60	    }
61	    guard let listener = SessionSocket.makeListener(path: socketPath) else {
62	      SessionIO.close(lock)
63	      return .failed("unable to listen on \(socketPath)")
64	    }
65	    return .running(
66	      SessionDaemon(
67	        socketPath: socketPath,
68	        idleTimeout: idleTimeoutMilliseconds,
69	        listener: listener,
70	        lockDescriptor: lock,
71	        signalPipe: signalPipe))
72	  }
73	
74	  private init(
75	    socketPath: String,
76	    idleTimeout: Int32,
77	    listener: Int32,
78	    lockDescriptor: Int32,
79	    signalPipe: SessionSignalPipe
80	  ) {
81	    self.socketPath = socketPath
82	    self.idleTimeout = idleTimeout
83	    self.listener = listener
84	    self.lockDescriptor = lockDescriptor
85	    self.signalPipe = signalPipe
86	  }
87	
88	  func run() {
89	    while true {
90	      let isIdle = sessions.isEmpty && connections.isEmpty
91	      var descriptors = buildPollDescriptors()
92	      let ready = poll(&descriptors, nfds_t(descriptors.count), pollTimeout(isIdle: isIdle))
93	      if ready == 0 {
94	        if processExpiredRedraws() { continue }
95	        guard sessions.isEmpty, connections.isEmpty else { continue }
96	        acceptConnections()
97	        guard connections.isEmpty else { continue }
98	        break
99	      }
100	      if ready < 0 {
101	        switch errno {
102	        case EINTR, EAGAIN, ENOMEM:
103	          continue
104	        default:
105	          SessionLog.write("poll failed: \(String(cString: strerror(errno)))")
106	          break
107	        }
108	        break
109	      }
110	      handle(descriptors)
111	      processExpiredRedraws()
112	      reapChildren()
113	      flushConnections()
114	      closeMarkedConnections()
115	    }
116	    shutdown()
117	  }
118	
119	  /// The nearest pending redraw's deadline overrides the ordinary idle/-1 timeout whenever one is
120	  /// outstanding, so the loop wakes up to resize-back-and-signal even with no other activity —
121	  /// without ever blocking inside a `usleep` the way the redraw used to.
122	  private func pollTimeout(isIdle: Bool) -> Int32 {
123	    guard let nearest = pendingRedraws.values.map(\.deadline).min() else {
124	      return isIdle ? idleTimeout : -1
125	    }
126	    let remainingMilliseconds = (nearest - SessionClock.monotonicSeconds()) * 1000
127	    return Int32(max(0, remainingMilliseconds.rounded(.up)))
128	  }
129	
130	  /// Resize each expired pending redraw back to its real size and signal, non-blockingly. Collects
131	  /// expired keys into a copy first — mutating `pendingRedraws` while iterating it directly is
132	  /// unsafe. A session that died before its deadline is silently dropped: nothing to resize.
133	  @discardableResult
134	  private func processExpiredRedraws() -> Bool {
135	    guard !pendingRedraws.isEmpty else { return false }
136	    let now = SessionClock.monotonicSeconds()
137	    let expired = pendingRedraws.filter { $0.value.deadline <= now }
138	    guard !expired.isEmpty else { return false }
139	    for (identifier, pending) in expired {
140	      pendingRedraws.removeValue(forKey: identifier)
141	      guard let session = sessions[identifier] else { continue }
142	      SessionPTY.resize(
143	        masterDescriptor: session.masterDescriptor, columns: pending.columns, rows: pending.rows)
144	      SessionPTY.requestRedraw(
145	        masterDescriptor: session.masterDescriptor, fallbackProcessID: session.processID)
146	    }
147	    return true
148	  }
149	
150	  private func shutdown() {
151	    for session in Array(sessions.values) {
152	      closeMaster(session)
153	    }
154	    for descriptor in connections.keys {
155	      SessionIO.close(descriptor)
156	    }
157	    SessionIO.close(listener)
158	    unlink(socketPath)
159	    // Deliberately NOT unlinking the lock file: closing this descriptor releases the flock on
160	    // its inode, but the path stays put so the next daemon's `acquireLock` opens the SAME inode
161	    // and re-flocks it. Unlinking here would leave a window where the path still exists but is
162	    // unlocked — a racing daemon could open+flock that inode before we unlink it, and a THIRD
163	    // daemon started after our unlink would then create a brand-new inode and also succeed,
164	    // leaving two daemons simultaneously believing they're the sole instance.
165	    SessionIO.close(lockDescriptor)
166	  }
167	
168	  private func buildPollDescriptors() -> [pollfd] {
169	    var descriptors: [pollfd] = [
170	      pollfd(fd: listener, events: Int16(POLLIN), revents: 0),
171	      pollfd(fd: signalPipe.readDescriptor, events: Int16(POLLIN), revents: 0),
172	    ]
173	    for connection in connections.values {
174	      var events = Int32(POLLIN)
175	      if connection.hasPendingOutput { events |= Int32(POLLOUT) }
176	      descriptors.append(pollfd(fd: connection.descriptor, events: Int16(events), revents: 0))
177	    }
178	    for session in sessions.values where session.masterDescriptor >= 0 {
179	      var events: Int32 = 0
180	      if !isClientBackedUp(session) { events |= Int32(POLLIN) }
181	      if session.hasPendingInput { events |= Int32(POLLOUT) }
182	      guard events != 0 else { continue }
183	      descriptors.append(pollfd(fd: session.masterDescriptor, events: Int16(events), revents: 0))
184	    }
185	    return descriptors
186	  }
187	
188	  private func isClientBackedUp(_ session: PTYSession) -> Bool {
189	    guard let descriptor = session.clientDescriptor,
190	      let connection = connections[descriptor]
191	    else { return false }
192	    return connection.pendingByteCount >= Self.clientOutputLimit
193	  }
194	
195	  private func handle(_ descriptors: [pollfd]) {
196	    for entry in descriptors where entry.revents != 0 {
197	      if entry.fd == listener {
198	        acceptConnections()
199	      } else if entry.fd == signalPipe.readDescriptor {
200	        signalPipe.drain()
201	      } else if connections[entry.fd] != nil {
202	        handleConnection(entry)
203	      } else if let identifier = sessionsByMaster[entry.fd] {
204	        handleMaster(entry, identifier: identifier)
205	      }
206	    }
207	  }
208	
209	  private func acceptConnections() {
210	    while let descriptor = SessionSocket.accept(listener) {
211	      guard connections.count < Self.maximumConnections else {
212	        SessionIO.close(descriptor)
213	        continue
214	      }
215	      guard SessionSocket.peerUserID(descriptor) == getuid() else {
216	        SessionLog.write("rejected connection from another user")
217	        SessionIO.close(descriptor)
218	        continue
219	      }
220	      connections[descriptor] = SessionConnection(descriptor: descriptor)
221	    }
222	  }
223	
224	  private func handleConnection(_ entry: pollfd) {
225	    guard let connection = connections[entry.fd] else { return }
226	    if entry.revents & Int16(POLLOUT) != 0, !connection.flush() {
227	      markForClose(entry.fd)
228	      return
229	    }
230	    guard entry.revents & Int16(POLLIN) != 0 || entry.revents & Int16(POLLHUP) != 0 else { return }
231	
232	    var reachedEnd = false
233	    readLoop: while true {
234	      switch SessionIO.read(entry.fd) {
235	      case .bytes(let bytes):
236	        connection.decoder.push(bytes)
237	      case .wouldBlock:
238	        break readLoop
239	      case .endOfFile, .failed:
240	        reachedEnd = true
241	        break readLoop
242	      }
243	    }
244	
245	    while true {
246	      do {
247	        guard let frame = try connection.decoder.next() else { break }
248	        handle(frame: frame, connection: connection)
249	      } catch {
250	        SessionLog.write("dropping connection with a malformed frame")
251	        markForClose(entry.fd)
252	        return
253	      }
254	    }
255	
256	    if reachedEnd { markForClose(entry.fd) }
257	  }
258	
259	  private func handle(frame: SessionFrame, connection: SessionConnection) {
260	    switch frame.kind {
261	    case .attach:
262	      handleAttach(payload: frame.payload, connection: connection)
263	    case .input:
264	      guard let identifier = connection.attachedSession, let session = sessions[identifier] else {
265	        return
266	      }
267	      session.appendInput(frame.payload, limit: Self.sessionInputLimit)
268	      session.flushInput()
269	    case .resize:
270	      guard let identifier = connection.attachedSession,
271	        let session = sessions[identifier],
272	        let size = try? SessionResizePayload.decode(frame.payload)
273	      else { return }
274	      guard SessionWindowSizePolicy.isUsable(columns: size.columns, rows: size.rows) else { return }
275	      SessionPTY.resize(
276	        masterDescriptor: session.masterDescriptor, columns: size.columns, rows: size.rows)
277	    case .list:
278	      connection.enqueue(
279	        SessionFrame(
280	          kind: .sessions,
281	          payload: SessionDescriptor.encodeList(sessions.values.map(\.descriptor))))
282	    case .info:
283	      guard let identifier = try? SessionIdentifierPayload.decode(frame.payload) else { return }
284	      let matches = sessions[identifier].map { [$0.descriptor] } ?? []
285	      connection.enqueue(
286	        SessionFrame(kind: .sessions, payload: SessionDescriptor.encodeList(matches)))
287	    case .kill:
288	      let stopped: Bool
289	      if let identifier = try? SessionIdentifierPayload.decode(frame.payload),
290	        let session = sessions[identifier]
291	      {
292	        stopped = endSession(session, status: 0, force: true)
293	      } else {
294	        stopped = true
295	      }
296	      enqueueStopResult(stopped, connection: connection)
297	    case .killAll:
298	      enqueueStopResult(endSessions(Array(sessions.values), status: 0), connection: connection)
299	    case .attached, .output, .exited, .failure, .sessions, .acknowledged:
300	      break
301	    }
302	  }
303	
304	  private func handleAttach(payload: [UInt8], connection: SessionConnection) {
305	    guard let request = try? SessionAttachRequest.decode(payload) else {
306	      connection.enqueue(
307	        SessionFrame(
308	          kind: .failure, payload: SessionTextPayload.encode("malformed attach request")))
309	      connection.closesAfterFlush = true
310	      return
311	    }
312	    guard request.version == SessionProtocolVersion.current else {
313	      connection.enqueue(
314	        SessionFrame(
315	          kind: .failure,
316	          payload: SessionTextPayload.encode(
317	            "this background session is owned by a different version of Workroom; stop it to start a new one"
318	          )))
319	      connection.closesAfterFlush = true
320	      return
321	    }
322	    guard connection.attachedSession == nil else { return }
323	
324	    if let session = sessions[request.identifier] {
325	      attach(session: session, request: request, connection: connection)
326	      return
327	    }
328	    create(request: request, connection: connection)
329	  }
330	
331	  private func attach(
332	    session: PTYSession, request: SessionAttachRequest, connection: SessionConnection
333	  ) {
334	    if let previous = session.clientDescriptor, previous != connection.descriptor {
335	      connections[previous]?.attachedSession = nil
336	      markForClose(previous)
337	    }
338	    session.clientDescriptor = connection.descriptor
339	    session.metadata = request.metadata
340	    connection.attachedSession = session.identifier
341	
342	    if SessionWindowSizePolicy.isUsable(columns: request.columns, rows: request.rows) {
343	      SessionPTY.resize(
344	        masterDescriptor: session.masterDescriptor,
345	        columns: request.columns,
346	        rows: request.rows)
347	    }
348	    connection.enqueue(
349	      SessionFrame(
350	        kind: .attached,
351	        payload: SessionAttachAccepted(
352	          created: false,
353	          shellProcessID: session.processID,
354	          ttyDevice: session.ttyDevice
355	        ).encoded()))
356	    // Synthesize a fresh title (OSC 2) and pwd (OSC 7) from the pty's CURRENT foreground process
357	    // before replaying anything. Both are normally set once by the shell's preexec/prompt hooks —
358	    // one-shot escapes emitted on the PRIMARY screen, before the foreground program (typically)
359	    // switches to the alternate screen — and `SessionReplayBuffer` drops its buffer the moment the
360	    // alternate screen activates, so a reattaching client never sees them; the foreground program
361	    // itself has no reason to re-emit either on the redraw `requestRedraw` forces. Excluding the
362	    // shell's own pgid (`forkpty` makes an idle prompt's foreground group equal `session.processID`)
363	    // keeps an idle reattached pane from showing a phantom "zsh"/"bash" title and stale pwd.
364	    if let group = SessionPTY.foregroundProcessGroup(masterDescriptor: session.masterDescriptor),
365	      group != session.processID
366	    {
367	      // Sanitized before ANY use below — both the log line and the OSC payloads. `name`/`cwd` come
368	      // from OS process introspection (an exec'd argv[0], a directory's real name) and can legally
369	      // contain any byte a filesystem path or exec argument allows, including a raw ESC or BEL. Left
370	      // unsanitized, such a byte would prematurely terminate the OSC 2/7 sequence it's interpolated
371	      // into (from the terminal's perspective) and let the remainder be reinterpreted as fresh,
372	      // attacker-chosen escape/terminal input in the reattaching client.
373	      let name = SessionPTY.executableName(processID: group).map(Self.sanitizedForEscapeSequence)
374	      let cwd = SessionPTY.workingDirectory(processID: group).map(Self.sanitizedForEscapeSequence)
375	      SessionLog.write(
376	        "attach \(session.identifier.uuidString): foreground pgid=\(group) name="
377	          + "\(name ?? "?") cwd=\(cwd ?? "?")")
378	      if let name, !name.isEmpty {
379	        connection.enqueue(
380	          SessionFrame(kind: .output, payload: Array("\u{1B}]2;\(name)\u{07}".utf8)))
381	      }
382	      if let cwd, !cwd.isEmpty {
383	        // Ghostty's OSC 7 handler validates the host against the local machine's hostname before
384	        // accepting the path (`internal_os.hostname.isLocal`) — except for the literal string
385	        // "localhost", which it special-cases as always-local. A locally-forked pty is never
386	        // remote, so that's the simpler, mismatch-proof choice over resolving the real hostname.
387	        connection.enqueue(
388	          SessionFrame(
389	            kind: .output, payload: Array("\u{1B}]7;kitty-shell-cwd://localhost\(cwd)\u{07}".utf8)))
390	      }
391	    } else {
392	      SessionLog.write(
393	        "attach \(session.identifier.uuidString): foreground is the login shell "
394	          + "(pid=\(session.processID)); skipping title/pwd synthesis")
395	    }
396	    enqueueReplay(session: session, connection: connection)
397	    // Query the CURRENT size fresh rather than trusting `request.columns/rows` — those may have
398	    // been rejected as unusable above (a transient tiny size from a not-yet-laid-out surface), in
399	    // which case the redraw must still bump from/to whatever size the session's pty actually has.
400	    //
401	    // The bump happens now (cheap, a single ioctl); the resize-back-and-signal is DEFERRED to the
402	    // poll loop (`processExpiredRedraws`), not done here inline with a blocking sleep — this daemon
403	    // is single-threaded and serves every session across every open project, so sleeping here would
404	    // freeze all of them for the duration, worst case stacking to N × the settle window when many
405	    // persisted tabs reattach at once on relaunch.
406	    if let current = SessionPTY.windowSize(descriptor: session.masterDescriptor) {
407	      SessionPTY.resize(
408	        masterDescriptor: session.masterDescriptor, columns: current.columns,
409	        rows: SessionPTY.bumpedRowCount(current.rows))
410	      pendingRedraws[session.identifier] = PendingRedraw(
411	        deadline: SessionClock.monotonicSeconds() + Self.redrawSettleSeconds,
412	        columns: current.columns, rows: current.rows)
413	    }
414	  }
415	
416	  private func enqueueReplay(session: PTYSession, connection: SessionConnection) {
417	    let bytes = session.replay.replayBytes
418	    guard !bytes.isEmpty else { return }
419	    SessionLog.write(
420	      "attach \(session.identifier.uuidString): replaying \(bytes.count) bytes: "
421	        + Self.escapedPreview(bytes))
422	    var index = 0
423	    while index < bytes.count {
424	      let end = min(index + Self.replayChunkSize, bytes.count)
425	      connection.enqueue(SessionFrame(kind: .output, payload: Array(bytes[index..<end])))
426	      index = end
427	    }
428	  }
429	
430	  private func create(request: SessionAttachRequest, connection: SessionConnection) {
431	    guard sessions.count < Self.maximumSessions else {
432	      connection.enqueue(
433	        SessionFrame(
434	          kind: .failure,
435	          payload: SessionTextPayload.encode("too many background sessions")))
436	      connection.closesAfterFlush = true
437	      return
438	    }
439	    let invocation = SessionShellIntegration.invocation(
440	      command: request.command,
441	      shell: request.shell,
442	      resourcesDirectory: request.resourcesDirectory,
443	      environment: request.environment)
444	    let size = SessionWindowSizePolicy.createSize(columns: request.columns, rows: request.rows)
445	    guard
446	      let process = SessionPTY.spawn(
447	        invocation: invocation,
448	        workingDirectory: request.workingDirectory,
449	        columns: size.columns,
450	        rows: size.rows)
451	    else {
452	      connection.enqueue(
453	        SessionFrame(
454	          kind: .failure, payload: SessionTextPayload.encode("failed to start the session")))
455	      connection.closesAfterFlush = true
456	      return
457	    }
458	
459	    let session = PTYSession(
460	      identifier: request.identifier,
461	      process: process,
462	      workingDirectory: request.workingDirectory,
463	      replayCapacity: Self.replayCapacity)
464	    session.clientDescriptor = connection.descriptor
465	    session.metadata = request.metadata
466	    sessions[request.identifier] = session
467	    sessionsByMaster[process.masterDescriptor] = request.identifier
468	    connection.attachedSession = request.identifier
469	
470	    connection.enqueue(
471	      SessionFrame(
472	        kind: .attached,
473	        payload: SessionAttachAccepted(
474	          created: true,
475	          shellProcessID: process.processID,
476	          ttyDevice: process.ttyDevice
477	        ).encoded()))
478	  }
479	
480	  private func handleMaster(_ entry: pollfd, identifier: SessionIdentifier) {
481	    guard let session = sessions[identifier] else { return }
482	    if entry.revents & Int16(POLLOUT) != 0 {
483	      session.flushInput()
484	    }
485	    guard
486	      entry.revents & Int16(POLLIN) != 0
487	        || entry.revents & Int16(POLLHUP) != 0
488	        || entry.revents & Int16(POLLNVAL) != 0
489	    else { return }
490	
491	    readLoop: while true {
492	      switch SessionIO.read(session.masterDescriptor) {
493	      case .bytes(let bytes):
494	        session.replay.append(bytes)
495	        if let descriptor = session.clientDescriptor, let connection = connections[descriptor] {
496	          connection.enqueue(SessionFrame(kind: .output, payload: bytes))
497	        }
498	        if isClientBackedUp(session) { break readLoop }
499	      case .wouldBlock:
500	        break readLoop
501	      case .endOfFile, .failed:
502	        closeMaster(session)
503	        return
504	      }
505	    }
506	  }
507	
508	  private func closeMaster(_ session: PTYSession) {
509	    guard session.masterDescriptor >= 0 else { return }
510	    sessionsByMaster.removeValue(forKey: session.masterDescriptor)
511	    SessionIO.close(session.masterDescriptor)
512	    session.masterDescriptor = -1
513	    session.isEnding = true
514	    SessionPTY.terminate(processID: session.processID)
515	  }
516	
517	  @discardableResult
518	  private func endSession(_ session: PTYSession, status: Int32, force: Bool = false) -> Bool {
519	    closeMaster(session)
520	    guard !force || SessionPTY.forceTerminate(processID: session.processID) else {
521	      SessionLog.write("failed to stop session \(session.identifier.uuidString)")
522	      return false
523	    }
524	    finishSession(session, status: status)
525	    return true
526	  }
527	
528	  private func endSessions(_ endingSessions: [PTYSession], status: Int32) -> Bool {
529	    for session in endingSessions { closeMaster(session) }
530	    let failedProcessIDs = SessionPTY.forceTerminate(processIDs: endingSessions.map(\.processID))
531	    for session in endingSessions where !failedProcessIDs.contains(session.processID) {
532	      finishSession(session, status: status)
533	    }
534	    for session in endingSessions where failedProcessIDs.contains(session.processID) {
535	      SessionLog.write("failed to stop session \(session.identifier.uuidString)")
536	    }
537	    return failedProcessIDs.isEmpty
538	  }
539	
540	  private func finishSession(_ session: PTYSession, status: Int32) {
541	    sessions.removeValue(forKey: session.identifier)
542	    guard let descriptor = session.clientDescriptor, let connection = connections[descriptor]
543	    else { return }
544	    connection.enqueue(
545	      SessionFrame(kind: .exited, payload: SessionExitPayload.encode(status: status)))
546	    connection.attachedSession = nil
547	    connection.closesAfterFlush = true
548	    session.clientDescriptor = nil
549	  }
550	
551	  private func enqueueStopResult(_ stopped: Bool, connection: SessionConnection) {
552	    let frame =
553	      stopped
554	      ? SessionFrame(kind: .acknowledged)
555	      : SessionFrame(
556	        kind: .failure, payload: SessionTextPayload.encode("failed to stop one or more sessions"))
557	    connection.enqueue(frame)
558	  }
559	
560	  private func reapChildren() {
561	    while true {
562	      var status: Int32 = 0
563	      let processID = waitpid(-1, &status, WNOHANG)
564	      guard processID > 0 else { return }
565	      guard let session = sessions.values.first(where: { $0.processID == processID }) else {
566	        continue
567	      }
568	      endSession(session, status: Self.exitCode(status))
569	    }
570	  }
571	
572	  static func exitCode(_ status: Int32) -> Int32 {
573	    let terminationSignal = status & 0o177
574	    if terminationSignal == 0 { return (status >> 8) & 0xFF }
575	    if terminationSignal == 0o177 { return 0 }
576	    return 128 + terminationSignal
577	  }
578	
579	  /// Renders bytes for a log line: printable ASCII passes through, `ESC` becomes `<ESC>` (so
580	  /// escape-sequence boundaries are visible at a glance), everything else becomes `\xNN`. Capped so
581	  /// one attach with a large buffer can't blow up the log file.
582	  private static func escapedPreview(_ bytes: [UInt8], limit: Int = 2048) -> String {
583	    let hexDigits = Array("0123456789ABCDEF")
584	    var result = ""
585	    for byte in bytes.prefix(limit) {
586	      switch byte {
587	      case 0x1B:
588	        result += "<ESC>"
589	      case 0x20...0x7E:
590	        result.append(Character(UnicodeScalar(byte)))
591	      default:
592	        result += "\\x"
593	        result.append(hexDigits[Int(byte >> 4)])
594	        result.append(hexDigits[Int(byte & 0x0F)])
595	      }
596	    }
597	    if bytes.count > limit { result += "…(+\(bytes.count - limit) more bytes)" }
598	    return result
599	  }
600	
601	  /// Strips C0 controls (0x00–0x1F), DEL (0x7F), and C1 controls (0x80–0x9F) — the bytes an 8-bit
602	  /// or 7-bit terminal could read as an escape/CSI/OSC introducer or terminator — from a value
603	  /// before it's interpolated into an OSC payload or a log line. `name`/`cwd` come from OS process
604	  /// introspection (`SessionPTY.executableName`/`workingDirectory`), not from this daemon's own
605	  /// generated data, so they must be treated as untrusted content here.
606	  private static func sanitizedForEscapeSequence(_ value: String) -> String {
607	    String(
608	      String.UnicodeScalarView(
609	        value.unicodeScalars.filter { scalar in
610	          scalar.value >= 0x20 && scalar.value != 0x7F
611	            && !(0x80...0x9F).contains(scalar.value)
612	        }))
613	  }
614	
615	  private func flushConnections() {
616	    for connection in connections.values {
617	      if !connection.flush() {
618	        markForClose(connection.descriptor)
619	        continue
620	      }
621	      if connection.closesAfterFlush, !connection.hasPendingOutput {
622	        markForClose(connection.descriptor)
623	      }
624	    }
625	  }
626	
627	  private func markForClose(_ descriptor: Int32) {
628	    guard !closingDescriptors.contains(descriptor) else { return }
629	    closingDescriptors.append(descriptor)
630	  }
631	
632	  private func closeMarkedConnections() {
633	    let descriptors = closingDescriptors
634	    closingDescriptors.removeAll(keepingCapacity: true)
635	    for descriptor in descriptors {
636	      guard let connection = connections.removeValue(forKey: descriptor) else { continue }
637	      if let identifier = connection.attachedSession,
638	        let session = sessions[identifier],
639	        session.clientDescriptor == descriptor
640	      {
641	        session.clientDescriptor = nil
642	      }
