266	      var name: [Int32] = [CTL_KERN, KERN_PROC, KERN_PROC_ALL]
267	      var size = 0
268	      guard sysctl(&name, 3, nil, &size, nil, 0) == 0, size > 0 else { return nil }
269	
270	      var records = [kinfo_proc](repeating: kinfo_proc(), count: size / stride + 16)
271	      size = records.count * stride
272	      if sysctl(&name, 3, &records, &size, nil, 0) != 0 {
273	        guard errno == ENOMEM else { return nil }
274	        continue
275	      }
276	
277	      var members: [pid_t: [pid_t]] = [:]
278	      for record in records.prefix(size / stride) {
279	        let processID = record.kp_proc.p_pid
280	        guard processID > 0 else { continue }
281	        let sessionID = getsid(processID)
282	        guard sessionIDs.contains(sessionID) else { continue }
283	        members[sessionID, default: []].append(processID)
284	      }
285	      return members
286	    }
287	    return nil
288	  }
