  let processID: pid_t
  let ttyDevice: UInt64
}

enum SessionPTY {
  private static let resetSignals: [Int32] = [
    SIGPIPE, SIGCHLD, SIGHUP, SIGINT, SIGQUIT, SIGTERM, SIGTSTP, SIGTTIN, SIGTTOU,
