      ws_ypixel: 0)
    var master: Int32 = -1
    var name = [CChar](repeating: 0, count: Int(PATH_MAX))

    let processID = forkpty(&master, &name, nil, &size)
    if processID < 0 {
      SessionLog.write("forkpty failed: \(String(cString: strerror(errno)))")
