51	public enum SessionShellIntegration {
52	  public static let defaultShell = "/bin/zsh"
53	  private static let posixShell = "/bin/sh"
54	  private static let xdgFallbackDataDirectories = "/usr/local/share:/usr/share"
55	
56	  public static func invocation(
57	    command: String,
58	    shell: String,
59	    resourcesDirectory: String,
60	    environment: [SessionEnvironmentEntry]
61	  ) -> SessionShellInvocation {
62	    let resolvedShell = shell.isEmpty ? defaultShell : shell
63	    let name = shellName(resolvedShell)
64	    var environment = SessionEnvironment(environment)
65	    var arguments = ["-" + name]
66	
67	    if !resourcesDirectory.isEmpty {
68	      environment["GHOSTTY_RESOURCES_DIR"] = resourcesDirectory
69	      let root = resourcesDirectory + "/shell-integration"
70	      switch name {
71	      case "zsh":
72	        applyZshIntegration(root: root, environment: &environment)
73	      case "bash":
74	        applyBashIntegration(root: root, environment: &environment)
75	        if command.isEmpty {
76	          arguments.append("--posix")
77	        }
78	      case "fish", "elvish", "nu":
79	        applyXDGIntegration(root: root, environment: &environment)
80	      default:
81	        break
82	      }
83	    }
84	
85	    guard command.isEmpty else {
86	      return SessionShellInvocation(
87	        executable: posixShell,
88	        arguments: [posixShell, "-c", "exec " + command],
89	        environment: environment.entries)
90	    }
91	
92	    return SessionShellInvocation(
93	      executable: resolvedShell,
94	      arguments: arguments,
95	      environment: environment.entries)
96	  }
97	
98	  public static func shellName(_ shell: String) -> String {
99	    guard let separator = shell.lastIndex(of: "/") else { return shell }
100	    return String(shell[shell.index(after: separator)...])
101	  }
102	
103	  private static func applyZshIntegration(root: String, environment: inout SessionEnvironment) {
104	    if let existing = environment["ZDOTDIR"] {
105	      environment["GHOSTTY_ZSH_ZDOTDIR"] = existing
106	    }
107	    environment["ZDOTDIR"] = root + "/zsh"
108	  }
109	
110	  private static func applyBashIntegration(root: String, environment: inout SessionEnvironment) {
111	    if let existing = environment["ENV"] {
112	      environment["GHOSTTY_BASH_ENV"] = existing
113	    }
114	    environment["ENV"] = root + "/bash/ghostty.bash"
115	    environment["GHOSTTY_BASH_INJECT"] = "1"
116	    if environment["HISTFILE"] == nil, let home = environment["HOME"], !home.isEmpty {
117	      environment["HISTFILE"] = home + "/.bash_history"
118	      environment["GHOSTTY_BASH_UNEXPORT_HISTFILE"] = "1"
119	    }
120	  }
121	
122	  private static func applyXDGIntegration(root: String, environment: inout SessionEnvironment) {
123	    environment["GHOSTTY_SHELL_INTEGRATION_XDG_DIR"] = root
124	    guard let existing = environment["XDG_DATA_DIRS"], !existing.isEmpty else {
125	      environment["XDG_DATA_DIRS"] = root + ":" + xdgFallbackDataDirectories
126	      return
127	    }
128	    guard !existing.split(separator: ":").contains(where: { $0 == root }) else { return }
