        _ = chdir(home)
      } else {
        _ = chdir("/")
      }
    }
    execve(executable, argumentList.pointer, environmentList.pointer)
    var failureErrno = errno
    withUnsafeBytes(of: &failureErrno) { bytes in
      _ = Darwin.write(execErrorWriteDescriptor, bytes.baseAddress, bytes.count)
    }
    _exit(127)
  }

